const getAgentAvatarAccessoryLayers = (
  accessory: AgentAvatarAccessory | undefined,
): { body?: React.ReactNode; face?: React.ReactNode } => {
  switch (accessory) {
    case undefined:
      return {};
    case 'cap':
      return { body: <Cap /> };
    case 'red-cap':
      return { body: <RedCap /> };
    case 'hair':
      return { body: <Hair /> };
    case 'curly-hair':
      return { body: <CurlyHair /> };
    case 'glasses':
      return { face: <Glasses /> };
    case 'sunglasses':
      return { face: <Sunglasses /> };
    case 'bob':
      return { body: <Bob /> };
    case 'headphones':
      return { body: <Headphones /> };
    case 'helmet':
      return { body: <Helmet /> };
    case 'backwards-cap':
      return { body: <BackwardsCap /> };
    case 'beard':
      return { body: <Beard /> };
    case 'top-hat':
      return { body: <TopHat /> };
    case 'beret':
      return { body: <Beret /> };
    case 'cowboy-hat':
      return { body: <CowboyHat /> };
    case 'crown':
      return { body: <Crown /> };
    case 'pirate-hat':
      return { body: <PirateHatBody />, face: <PirateHatFace /> };
    case 'earmuffs':
      return { body: <Earmuffs /> };
    case 'goggles':
      return { body: <Goggles /> };
    case 'mohawk':
      return { body: <Mohawk /> };
    case 'buns':
      return { body: <Buns /> };
    case 'chef-hat':
      return { body: <ChefHat /> };
    case 'hard-hat':
      return { body: <HardHat /> };
    case 'grandpa':
      return { body: <GrandpaBody />, face: <GrandpaFace /> };
    case 'wizard-hat':
      return { body: <WizardHat /> };
    case 'santa-hat':
      return { body: <SantaHat /> };
    case 'bucket-hat':
      return { body: <BucketHat /> };
    case 'graduation-cap':
      return { body: <GraduationCap /> };
    case 'robot':
      return { body: <Robot /> };
    case 'aviator-cap':
      return { body: <AviatorCap /> };
    case 'nurse-cap':
      return { body: <NurseCap /> };
    case 'afro':
      return { body: <Afro /> };
    case 'punk-hair':
      return { body: <PunkHair /> };
    case 'fox-ears':
      return { body: <FoxEars /> };
    case 'sailor-hat':
      return { body: <SailorHat /> };
    case 'nightcap':
      return { body: <Nightcap /> };
    case 'balaclava':
      return { body: <Balaclava /> };
    case 'tinfoil-hat':
      return { body: <TinfoilHat /> };
    case 'pot':
      return { body: <Pot /> };
    case 'duck':
      return { body: <Duck /> };
    case 'flamingo':
      return { body: <Flamingo /> };
    case 'octopus':
      return { body: <Octopus /> };
    case 'fried-egg':
      return { body: <FriedEgg /> };
    case 'disguise':
      return { face: <Disguise /> };
    case 'popcorn':
      return { body: <Popcorn /> };
    case 'ufo':
      return { body: <Ufo /> };
    case 'bow':
      return { body: <Bow /> };
    case 'cactus':
      return { body: <Cactus /> };
  }
};

export { agentAvatarAccessoriesList, getAgentAvatarAccessoryLayers };
export type { AgentAvatarAccessory };
